<script setup>
import {ref,watch} from 'vue';import axios from 'axios';import {ElMessage} from 'element-plus';import {errorMessage} from '../utils/operations';
const props=defineProps({order:Object}),emit=defineEmits(['changed']);const data=ref(null),error=ref(''),busy=ref(false);const labels={NO_BOM:'未配置 BOM',UNRESERVED:'尚未预留',RESERVED:'已预留',RELEASED:'已释放',CONSUMED:'已领料'};
async function load(){error.value='';try{data.value=(await axios.get('/api/inventory/orders/'+props.order.id)).data}catch(e){error.value=errorMessage(e)}}
watch(()=>[props.order.id,props.order.version],load,{immediate:true});
async function act(action){busy.value=true;try{await axios.post('/api/inventory/orders/'+props.order.id+'/'+action,{version:props.order.version});emit('changed');await load();ElMessage.success('物料记录已更新')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script><template><section class="order-materials"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="data"><div class="inventory-section-heading"><h3>{{labels[data.status]}} <small v-if="data.bomVersion">· BOM 修订 {{data.bomVersion}}</small></h3><span>按订单数量计算</span></div><p v-if="data.status==='NO_BOM'" class="hint">此产品尚未配置 BOM，不参与物料预留。可在物料与 BOM 中按产品名称配置。</p><el-table v-else :data="data.lines" size="small"><el-table-column prop="sku" label="物料编号"/><el-table-column prop="quantity" label="需求数量"/><el-table-column prop="available" label="可用库存"/><el-table-column prop="unit" label="单位"/></el-table><div v-if="order.status==='ACCEPTED'" class="inventory-actions"><el-button v-if="['UNRESERVED','RELEASED'].includes(data.status)" type="primary" :loading="busy" @click="act('reserve')">预留全部用料</el-button><el-button v-if="data.status==='RESERVED'" :loading="busy" @click="act('release')">释放预留</el-button></div><p class="hint" v-if="data.status==='RESERVED'">已保存用料快照；后续 BOM 修改不会改变本单预留。开始生产时自动领料，暂停后恢复不会重复扣减。</p></template></section></template>